<script setup lang="ts">import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api}from'../../api/client';import type{SupportCase}from'../../domain/types';const c=ref<SupportCase|null>(null),loading=ref(false),error=ref('');async function refresh(){loading.value=true;error.value='';try{c.value=await api.getSupportCase()}catch{error.value='暂时无法更新，请稍后重试。'}finally{loading.value=false}}onLoad(refresh)</script>
<template><view class="page"><AppHeader left="返回" right="订单" @left="uni.navigateBack()" @right="uni.navigateTo({url:'/pages/order/list'})"/><view class="content"><view class="heading" role="heading" aria-level="1">在线帮助</view><text class="desc">我们会根据当前订单情况继续查询并更新结果。</text><StatusNotice v-if="error" tone="risk" title="暂时无法更新">{{error}}</StatusNotice><view class="card"><view class="kv"><text>当前进度</text><text>{{c?.confirmed||'正在查询'}}</text></view><view class="kv"><text>仍需确认</text><text>{{c?.unknown||'请稍后查看'}}</text></view><view class="kv"><text>处理方式</text><text>{{c?.responsibility||'我们会继续跟进'}}</text></view><view class="kv"><text>下次更新</text><text>{{c?.nextReviewAt||'有结果后及时更新'}}</text></view></view></view><view class="action"><button class="primary" :disabled="loading" @click="refresh">刷新处理进度</button><button class="secondary" @click="uni.reLaunch({url:'/pages/index/index'})">返回首页</button></view></view></template><style src="../../styles/shared.css"></style>
